#!/usr/bin/env bash
# Rasterise packaging/icon.svg into a macOS .icns app icon.
#
# packaging/icon.svg is generated by scripts/build-wordmark.swift -- edit the
# wordmark there (font, text, size) and re-run it before this script.
#
# Requires: rsvg-convert (brew install librsvg) + iconutil (Xcode CLT).
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"

SVG="packaging/icon.svg"
ICNS="packaging/AppIcon.icns"
# The .iconset is a build intermediate, so keep it out of the repo.
ICONSET="$ROOT/dist/AppIcon.iconset"

if ! command -v rsvg-convert >/dev/null 2>&1; then
    echo "error: rsvg-convert not found (brew install librsvg)" >&2
    exit 1
fi

rm -rf "$ICONSET"
mkdir -p "$ICONSET"

# The sizes macOS looks for in an .icns; each at 1x and @2x.
for size in 16 32 128 256 512; do
    rsvg-convert -w "$size" -h "$size" "$SVG" -o "$ICONSET/icon_${size}x${size}.png"
    rsvg-convert -w "$((size * 2))" -h "$((size * 2))" \
        "$SVG" -o "$ICONSET/icon_${size}x${size}@2x.png"
done

iconutil --convert icns --output "$ICNS" "$ICONSET"
rm -rf "$ICONSET"

echo "Wrote $ICNS"
